import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-105: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short105', durationInSeconds: 37.4, fps: 30, width: 1080, height: 1920 };

const B1 = secToFrame(7.2);
const B2 = secToFrame(13.1);
const B3 = secToFrame(22.9);
const B4 = secToFrame(27.1);
const CTA = secToFrame(34.5);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const HOOK = [{ text: 'GOOGLE 18¢' }, { text: 'MICROSOFT 54¢', accent: true }];

const Short105: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-105/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="AI TRANSCRIPTION PRICING" lines={HOOK} />
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="Gemini 3.5 Transcribe" tagline="Google's speech-to-text API." chip="18¢ / HR" at={B1 + 4}>
          <Panel>
            <Line k="price / minute" v="$0.003" good />
            <Line k="price / hour" v="~$0.18" good />
            <Line k="free tier" v="yes" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="MAI-Transcribe-2-Streaming" tagline="Microsoft's streaming transcriber." chip="54¢ / HR" at={B2 + 4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="price / hour" v="$0.54" bad />
            <Line k="vs Google" v="3x" bad />
            <Line k="rate" v="introductory" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="Gemini 3.5 Transcribe Live" tagline="Google's live version." chip="30¢ / HR" at={B3 + 4}>
          <Panel>
            <Line k="price / minute" v="$0.005" good />
            <Line k="price / hour" v="$0.30" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Per hour of audio" tagline="Do the math." chip="VERDICT" at={B4 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Gemini Transcribe" v="$0.18" good />
            <Line k="Gemini Live" v="$0.30" />
            <Line k="MAI Streaming" v="$0.54" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-105/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="AI TRANSCRIPTION PRICING" lines={HOOK} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 720, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Check the price per hour.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short105;
